async function scan(){
 const state={files:0,directories:0,bytes:0,links:[]};
 async function walk(p){
  const s=await lstat(p);
  if(s.isSymbolicLink()){state.links.push(p);return;}
  if(s.isDirectory()){
   if(normalize(await realpath(p))!==normalize(p)){state.links.push(p);return;}
   state.directories++;for(const n of await readdir(p))await walk(path.join(p,n));
